self.FRX=self.FRX||{};(FRX.gx=FRX.gx||{})["tr"]={"etre-present":["Être: olmak","\"être\" 'olmak' demektir: \"je suis\", \"tu es\", \"il est\", \"nous sommes\", \"vous êtes\", \"ils sont\". Kimlik, köken, meslek ve tarif için kullanılır. Ezberleyin, Fransızcadaki en sık kullanılan fiildir. Örnekler: \"je suis\", \"nous sommes\", \"ils sont\"."],"avoir-present":["Avoir: sahip olmak","\"avoir\" 'sahip olmak' demektir: \"j'ai\", \"tu as\", \"il a\", \"nous avons\", \"vous avez\", \"ils ont\". Daha sonra passé composé'yi de kurar. Ünlü sesten önce \"j'ai\" biçimindeki ünlü düşmesine dikkat edin. Örnekler: \"j'ai\", \"elle a\", \"nous avons\"."],"il-y-a":["Il y a: var","\"il y a\" var olan bir şeyi tanıtır; tekil de çoğul da olur ve hiç değişmez: \"il y a un livre\", \"il y a des livres\". Olumsuz: \"il n'y a pas de livre\". Soru: \"y a-t-il\" ya da \"est-ce qu'il y a\". Örnekler: \"il y a un café\", \"il n'y a pas de lait\"."],"art-defini":["Belirli tanımlıklar","\"le\" (eril), \"la\" (dişil), \"l'\" (ünlüden önce) ve \"les\" (çoğul) 'the' anlamına gelir. Fransızca genel fikirlerde de bunları kullanır: \"j'aime la musique\" 'müzikten hoşlanırım' demektir. Örnekler: \"le café\", \"la pomme\", \"les enfants\"."],"art-indefini":["Belirsiz tanımlıklar","\"un\" (eril), \"une\" (dişil) ve \"des\" (çoğul) 'bir' ya da 'bazı' demektir. Yeni bir şeyi tanıtır: \"j'ai un frère et des cousins\". \"des\" Türkçede çoğu zaman karşılanmaz. Örnekler: \"un frère\", \"une sœur\", \"des amis\"."],"gender-nouns":["Eril mi, dişil mi?","Her isim ya eril ya dişildir. Sonekler yardımcı olur: \"-tion\", \"-té\", \"-ette\" çoğunlukla dişil; \"-ment\", \"-age\", \"-eau\" çoğunlukla eril. İsmi hep tanımlığıyla öğrenin: \"la ville\", \"le village\". Örnekler: \"le village\", \"la ville\", \"la question\"."],"plural-regular":["Çoğul: -s ekle","Çoğu çoğul \"-s\" alır ve bu okunmaz: \"un ami\", \"des amis\". Zaten \"-s\", \"-x\" veya \"-z\" ile biten isimler değişmez: \"un pays\", \"des pays\". Çoğulu yalnızca tanımlık ve liaison belli eder. Örnekler: \"deux sœurs\", \"trois amis\"."],"plural-irregular":["Düzensiz çoğullar","\"-al\" ile biten isimler \"-aux\" olur: \"un journal\", \"des journaux\". \"-eau\" ve \"-eu\" ile bitenler \"-x\" alır: \"un bateau\", \"des bateaux\", \"un jeu\", \"des jeux\". \"un festival, des festivals\" gibi az sayıdaki istisnayı öğrenin. Örnekler: \"des journaux\", \"des bateaux\", \"des cheveux\"."],"elision-basic":["Ünlüden önce düşme","\"le\", \"la\", \"je\", \"ne\", \"de\", \"que\", \"se\" gibi kısa sözcükler ünlü veya sessiz h'den önce ünlülerini kaybeder ve kesme işareti alır: \"l'école\", \"j'aime\", \"n'aime pas\", \"qu'elle\". \"les\" ve \"un\" asla düşmez. Örnekler: \"l'école\", \"j'aime\", \"qu'elle\"."],"contractions-au-du":["au, aux, du, des","\"à + le\" \"au\", \"à + les\" \"aux\", \"de + le\" \"du\", \"de + les\" \"des\" olur. \"la\" ve \"l'\" ile bir şey değişmez: \"à la gare\", \"de la gare\". Asla \"à le\" ya da \"de le\" yazmayın. Örnekler: \"au marché\", \"aux voisins\", \"du professeur\"."],"partitif":["Bölümlük: biraz","Sayılamayan bir şeyin miktarını anlatmak için \"du\" (eril), \"de la\" (dişil), \"de l'\" (ünlü) veya \"des\" (çoğul) kullanılır: \"je prends du café\". Türkçede burada çoğu zaman sözcük yoktur, Fransızcada her zaman vardır. Örnekler: \"du pain\", \"de la salade\", \"des légumes\"."],"de-negation":["Olumsuzluk + de","\"ne… pas\", \"jamais\", \"plus\" sonrasında belirsiz veya bölümlük tanımlık \"de\" olur: \"j'ai un chat\" -> \"je n'ai pas de chat\". İstisna: \"être\" sonrasında tanımlık kalır: \"ce n'est pas un chat\". Örnekler: \"pas de voiture\", \"jamais de viande\"."],"adj-agreement":["Sıfat uyumu","Sıfatlar isme uyar: dişil için \"-e\", çoğul için \"-s\" eklenir. \"grand\", \"grande\", \"grands\", \"grandes\". \"-e\" ile bitenler dişilde aynı kalır: \"un garçon sympa\", \"une fille sympa\". Örnekler: \"elle est grande\", \"ils sont petits\"."],"adj-position":["Sıfat nereye gider?","Çoğu sıfat isimden sonra gelir: \"une robe bleue\". Kısa ve sık birkaçı öne gelir: güzellik, yaş, iyilik, boyut (\"beau, jeune, bon, grand, petit\"): \"un petit chien\". \"beau\"nun \"bel\" ve \"belle\" biçimleri vardır. Örnekler: \"une belle maison\", \"une maison blanche\"."],"possessifs":["İyelik: mon, ma, mes","İyelik sözcüğü sahibe değil, sahip olunan şeye uyar: \"mon père\", \"ma mère\", \"mes parents\". Ünlüyle başlayan dişil isimlerden önce \"mon\" gelir: \"mon amie\". Diğerleri: \"notre/nos\", \"votre/vos\", \"leur/leurs\". Örnekler: \"mon père\", \"ma mère\", \"leurs chats\"."],"demonstratifs":["Bu, şu: ce, cette, ces","\"ce\" (eril), \"cet\" (ünlüden önce eril), \"cette\" (dişil) ve \"ces\" (çoğul) 'bu' ya da 'şu' demektir. Karşıtlık için \"-ci\" veya \"-là\" eklenir: \"ce livre-ci\", \"ce livre-là\". Örnekler: \"ce livre\", \"cette veste\", \"ces enfants\"."],"pres-er":["Présent: -er fiilleri","\"-er\" atılır ve \"-e, -es, -e, -ons, -ez, -ent\" eklenir: \"parler\" -> \"je parle\", \"tu parles\", \"il parle\", \"nous parlons\", \"vous parlez\", \"ils parlent\". Fransızca fiillerin yaklaşık yüzde 90'ı bu kalıba uyar. Örnekler: \"je parle\", \"nous parlons\", \"ils parlent\"."],"pres-ir-re":["Présent: -ir ve -re fiilleri","Düzenli \"-ir\" fiilleri \"-is, -is, -it, -issons, -issez, -issent\" alır: \"finir\", \"je finis\", \"nous finissons\". \"-re\" fiilleri \"-s, -s, -, -ons, -ez, -ent\" alır: \"vendre\", \"je vends\", \"il vend\". Örnekler: \"je finis\", \"nous finissons\", \"je vends\"."],"pres-irreguliers":["Sık düzensiz fiiller","Şunları öğrenin: \"aller\" (\"je vais, nous allons\"), \"faire\" (\"je fais, vous faites\"), \"prendre\" (\"je prends, ils prennent\") ve \"venir\" (\"je viens, ils viennent\"). \"vous faites\" ve \"ils font\" kalıbı bozar, dikkat. Örnekler: \"je vais\", \"nous faisons\", \"ils prennent\", \"vous venez\"."],"tu-vous":["Tu mu, vous mu?","\"tu\"yu arkadaş, aile, çocuk ve yaşıtlarla kullanın. \"vous\"yu yabancılarla, yaşlılarla, mağazada, işte ve birden fazla kişiye hitap ederken her zaman kullanın. Emin değilseniz \"vous\" ile başlayın. Örnekler: \"tu viens\", \"vous venez\"."],"on-nous":["On = biz","Günlük Fransızcada \"on\", \"nous\" yerine geçer ama fiil üçüncü tekil kişide kalır: \"on va au cinéma\". \"On\" ayrıca 'insanlar' anlamına da gelir: \"en France, on mange du pain\". Örnekler: \"on va\", \"on mange\"."],"neg-ne-pas":["Olumsuzluk: ne … pas","\"ne\" fiilden önce, \"pas\" fiilden sonra gelir: \"je ne parle pas\". Ünlüden önce \"ne\" \"n'\" olur: \"il n'aime pas\". Konuşmada \"ne\" sık atılır, ama doğru Fransızcada yazın. Örnekler: \"je ne parle pas\", \"il n'aime pas\"."],"q-est-ce-que":["Evet/hayır soruları","En kolayı: sözcük sırasını koruyup sesi yükseltmek ya da soru işareti koymak: \"tu viens ?\". Daha resmi: başa \"est-ce que\" koymak: \"est-ce que tu viens ?\". Ünlüden önce \"est-ce qu'\" olur: \"est-ce qu'elle vient ?\". Örnekler: \"tu aimes le thé ?\", \"est-ce que vous avez\"."],"q-mots-interrogatifs":["Soru sözcükleri","\"où\" (nerede), \"quand\" (ne zaman), \"comment\" (nasıl), \"combien\" (ne kadar), \"pourquoi\" (neden), \"qui\" (kim). Başa gelirler: \"où est la gare ?\". \"pourquoi\"ya \"parce que\" ile cevap verilir. Örnekler: \"où\", \"quand\", \"combien\", \"pourquoi\"."],"q-quel":["Quel: hangi, ne","\"quel\" isme uyar: \"quel\" (eril tekil), \"quelle\" (dişil tekil), \"quels\" (eril çoğul), \"quelles\" (dişil çoğul). \"être\" sonrasında isimden ayrı da gelebilir: \"quel est ton nom ?\" Örnekler: \"quelle heure\", \"quels films\"."],"futur-proche":["Yakın gelecek: aller + mastar","\"aller\" şimdiki zamanda çekilir ve bir mastar eklenir: \"je vais travailler\", \"nous allons manger\". Olumsuz: \"je ne vais pas partir\". Konuşmada planlardan söz etmenin olağan yoludur. Örnekler: \"je vais manger\", \"elle va partir\"."],"pres-pronominaux":["Dönüşlü fiiller","Bu fiillerde özneye uyan bir zamir bulunur: \"je me\", \"tu te\", \"il se\", \"nous nous\", \"vous vous\", \"ils se\". Örnekler: \"se lever\", \"se coucher\", \"s'habiller\". Olumsuz: \"je ne me lève pas\". Örnekler: \"je me lève\", \"elle se couche\"."],"imperatif-present":["Emir kipi","\"tu\", \"nous\", \"vous\" için şimdiki zaman biçimleri zamirsiz kullanılır: \"tu parles\" -> \"parle !\", \"nous parlons\" -> \"parlons !\", \"vous parlez\" -> \"parlez !\". \"-er\" fiilleri \"tu\" biçiminde son -s'yi atar. Düzensizler: \"sois, soyons, soyez\", \"aie, ayons, ayez\". Örnekler: \"parle !\", \"parlons !\", \"parlez !\"."],"modaux-pouvoir-vouloir":["vouloir, pouvoir, devoir","Bu üç fiilden sonra mastar gelir: \"je veux manger\", \"tu peux venir\", \"nous devons partir\". Düzensizdirler: \"je veux, nous voulons\", \"je peux, nous pouvons\", \"je dois, nous devons\". Örnekler: \"je veux partir\", \"tu peux\", \"nous devons\"."],"prep-lieu":["Nerede?","Sık yer sözcükleri: \"dans\" (içinde), \"sur\" (üstünde), \"sous\" (altında), \"devant\" (önünde), \"derrière\" (arkasında), \"entre\" (arasında), \"à côté de\" (yanında), \"près de\" (yakınında). \"de\" sonrasında kaynaşmaları unutmayın: \"à côté du parc\". Örnekler: \"sur la table\", \"sous la table\", \"entre la poste et la banque\"."],"prep-a-chez-de":["à, chez, de","\"à\" şehir ve yerlerle gelir: \"je vais à Lyon\". \"chez\" kişilerle veya onların dükkânı ya da evi ile gelir: \"chez le dentiste\", \"chez moi\". \"de\" nereden geldiğinizi söyler: \"je viens de Lyon\". Örnekler: \"chez Marie\", \"à Lyon\", \"de la gare\"."],"nombres":["Sayılar","Özel biçimler: \"soixante-dix\" (70), \"quatre-vingts\" (80, -s ile), \"quatre-vingt-dix\" (90). \"et\" 21, 31, 41, 51, 61 ve 71'de görünür; 81 ve 91'de görünmez. Onlukları ve birlikleri tire bağlar. Örnekler: \"vingt et un\", \"soixante-dix\", \"quatre-vingts\"."],"heure-date":["Saat ve tarih","\"il est\" + saat kullanın: \"il est trois heures et quart\". \"midi\" ve \"minuit\" \"et demi\", diğer saatler \"et demie\" alır. Tarih: \"le 5 mai\"; yalnızca 1'i sıra sayısıdır: \"le premier mai\". Saat için \"à\" kullanılır: \"à neuf heures\". Örnekler: \"huit heures et demie\", \"le cinq mai\"."],"c-est-ce-sont":["C'est, ce sont","Tanıtmak veya belirtmek için tekil isimle \"c'est\", çoğul isimle \"ce sont\" kullanın: \"c'est un livre\", \"ce sont des livres\". Konuşmada çoğulla da \"c'est\" yaygındır. Soru: \"qu'est-ce que c'est ?\" Örnekler: \"c'est mon frère\", \"ce sont mes amis\"."],"gouts-aimer":["Sevdikleriniz, sevmedikleriniz","\"aimer\", \"adorer\", \"détester\" ve \"préférer\" sonrasında bölümlük değil, belirli tanımlık kullanılır: \"j'aime le café\", \"elle adore les chats\". \"beaucoup\" ekleyebilirsiniz: \"j'aime beaucoup la musique\". Örnekler: \"j'aime le chocolat\", \"je déteste les épinards\"."],"adv-intensite":["Ne kadar?","\"très\" sıfat ve zarflardan önce gelir: \"très bien\". \"beaucoup\" fiillerden sonra gelir: \"il travaille beaucoup\". İsimden önce \"beaucoup de\" kullanılır: \"beaucoup de fruits\". \"un peu\" ve \"trop\" \"beaucoup\" gibi çalışır. Örnekler: \"très grand\", \"il mange beaucoup\", \"un peu\"."],"avoir-expressions":["avoir ifadeleri","Fransızca yaş ve birçok bedensel his için \"être\" değil \"avoir\" kullanır: \"j'ai vingt ans\", \"j'ai faim\", \"j'ai soif\", \"j'ai chaud\", \"j'ai froid\", \"j'ai peur\", \"j'ai sommeil\". \"très\" eklenebilir: \"j'ai très faim\". Örnekler: \"j'ai faim\", \"elle a vingt ans\", \"il a froid\"."],"clause-et-mais-parce-que":["Bağlaçlar","\"et\" ekler, \"ou\" seçenek verir, \"mais\" karşıtlık kurar, \"parce que\" neden bildirir. Ünlüden önce \"parce que\" \"parce qu'\" olur: \"parce qu'il pleut\". \"donc\" sonucu verir. Örnekler: \"et\", \"mais\", \"parce que\"."],"pc-avoir":["avoir ile passé composé","Çoğu fiil geçmişi şimdiki zamanda \"avoir\" + geçmiş zaman ortacı ile kurar: \"j'ai mangé\", \"tu as fini\", \"il a vendu\". Ortaçlar: \"-er\" -> \"-é\", \"-ir\" -> \"-i\", \"-re\" -> \"-u\". Örnekler: \"j'ai mangé\", \"nous avons fini\"."],"pc-etre":["être ile passé composé","Yaklaşık on beş fiil \"être\" alır: \"aller, venir, arriver, partir, entrer, sortir, monter, descendre, rester, tomber, naître, mourir, retourner, passer\" ve tüm dönüşlü fiiller. Ezber için \"DR MRS VANDERTRAMP\" listesi kullanılır. Örnekler: \"je suis allé\", \"elle est partie\"."],"pc-accord-etre":["être ile ortaç uyumu","\"être\" ile ortaç özneye uyar: dişil için \"-e\", çoğul için \"-s\". \"il est parti\", \"elle est partie\", \"ils sont partis\", \"elles sont parties\". Örnekler: \"elle est partie\", \"ils sont venus\", \"elles sont allées\"."],"pc-pronominaux":["Geçmişte dönüşlü fiiller","Dönüşlü fiiller \"être\" alır ve zamir onun önünde durur: \"je me suis levé\", \"elle s'est couchée\", \"ils se sont promenés\". Ortaç genellikle özneye uyar. Örnekler: \"je me suis levé\", \"elle s'est couchée\"."],"pc-negation":["Olumsuz geçmiş","\"ne … pas\" ortacı değil, yardımcı fiili sarar: \"je n'ai pas mangé\", \"elle n'est pas venue\". \"jamais\", \"plus\", \"rien\" ile de aynıdır: \"il n'a rien dit\". Örnekler: \"je n'ai pas mangé\", \"il n'est jamais venu\"."],"pc-participes-irreguliers":["Düzensiz ortaçlar","Mutlaka bilin: \"avoir\" -> \"eu\", \"être\" -> \"été\", \"faire\" -> \"fait\", \"prendre\" -> \"pris\", \"voir\" -> \"vu\", \"dire\" -> \"dit\", \"écrire\" -> \"écrit\", \"mettre\" -> \"mis\", \"pouvoir\" -> \"pu\", \"vouloir\" -> \"voulu\". Örnekler: \"j'ai eu\", \"j'ai été\", \"il a fait\", \"elle a pris\"."],"imparfait-formation":["Imparfait: biçimler","Présent'ın \"nous\" biçimini alın, \"-ons\" atın, \"-ais, -ais, -ait, -ions, -iez, -aient\" ekleyin: \"nous parlons\" -> \"je parlais\". Yalnızca \"être\" düzensizdir: \"j'étais, nous étions\". Örnekler: \"je jouais\", \"nous allions\", \"il était\"."],"imparfait-usage":["Imparfait: ne zaman?","\"imparfait\" bir hikâyenin fonu için kullanılır: hava, duygular, betimlemeler ve tekrarlanan alışkanlıklar. \"Il faisait beau\", \"j'étais fatigué\", \"chaque été, nous allions à la mer\". Örnekler: \"il faisait beau\", \"je jouais\", \"nous habitions\"."],"impf-vs-pc":["Imparfait mı, passé composé mu?","\"Imparfait\": olup bitmekte olan, ortam. \"Passé composé\": olan şey, hikâyeyi ilerleten tek olay. \"Je lisais quand le téléphone a sonné\": okuma sürüyordu, çalan telefon onu böldü. Örnekler: \"je dormais\", \"le téléphone a sonné\"."],"futur-simple":["Futur simple","Mastarı alın (\"-re\" fiillerinde son -e atılır) ve \"-ai, -as, -a, -ons, -ez, -ont\" ekleyin: \"parler\" -> \"je parlerai\", \"prendre\" -> \"je prendrai\". Örnekler: \"je parlerai\", \"nous prendrons\", \"ils finiront\"."],"futur-irreguliers":["Düzensiz gelecek kökleri","Ekler aynı kalır ama kök değişir: \"aller\" -> \"ir-\", \"être\" -> \"ser-\", \"avoir\" -> \"aur-\", \"faire\" -> \"fer-\", \"venir\" -> \"viendr-\", \"pouvoir\" -> \"pourr-\", \"voir\" -> \"verr-\", \"vouloir\" -> \"voudr-\". Örnekler: \"j'irai\", \"il fera\", \"ils viendront\"."],"conditionnel-politesse":["Nazik conditionnel","\"conditionnel\" ricaları yumuşatır: \"je voudrais\" (isterdim), \"pourriez-vous\" (yapabilir misiniz), \"j'aimerais\" (çok isterdim). Kuruluş: futur kökü + imparfait ekleri \"-ais, -ais, -ait, -ions, -iez, -aient\". Örnekler: \"je voudrais\", \"pourriez-vous\", \"nous aimerions\"."],"cod-pronoms":["Düz nesne zamirleri","\"le\", \"la\", \"l'\" ve \"les\" edatsız bir ismin yerini tutar ve fiilden önce gelir: \"je vois Paul\" -> \"je le vois\". Olumsuz: \"je ne le vois pas\". Örnekler: \"je le vois\", \"elle la prend\", \"tu les aimes\"."],"coi-pronoms":["Dolaylı nesne zamirleri","\"à\" sonrasındaki kişiler için \"lui\" (ona) ve \"leur\" (onlara) kullanılır: \"je parle à Marie\" -> \"je lui parle\", \"je téléphone à mes parents\" -> \"je leur téléphone\". \"leur\" burada asla -s almaz. Örnekler: \"je lui parle\", \"elle leur écrit\"."],"pronoms-me-te-nous-vous":["me, te, nous, vous","Bu dört zamir hem düz hem dolaylı nesne olur: \"il me voit\", \"il me parle\". Ünlüden önce \"me\" ve \"te\" \"m'\" ve \"t'\" olur: \"je t'aime\", \"il m'écoute\". Örnekler: \"il me voit\", \"elle nous parle\"."],"y-pronom":["y zamiri","\"y\", \"à\" + şey veya bir yerin yerini tutar: \"je vais à Rome\" -> \"j'y vais\". Fiilden önce gelir: \"nous y allons\", \"je n'y vais pas\". Ayrıca \"j'y pense\". Örnekler: \"j'y vais\", \"nous y allons\"."],"en-pronom":["en zamiri","\"en\", \"du, de la, des\" + isim veya \"de\" + isim yerine geçer. Sayı korunur: \"j'ai deux frères\" -> \"j'en ai deux\". Olumsuz: \"je n'en veux pas\". Örnekler: \"j'en veux\", \"nous en avons deux\"."],"pronoms-toniques":["Vurgulu zamirler","\"moi, toi, lui, elle, nous, vous, eux, elles\" edatlardan sonra (\"avec moi\", \"chez eux\"), vurgu için (\"moi, je\") ve tek başına (\"Qui est là ? Moi !\") kullanılır. \"c'est\" sonrasında da: \"c'est lui\". Örnekler: \"avec moi\", \"chez lui\", \"eux\"."],"comparatifs":["Karşılaştırma: plus … que","Bir sıfat veya zarfın etrafında \"plus … que\" (daha), \"moins … que\" (daha az) ve \"aussi … que\" (kadar) kullanın: \"elle est plus rapide que lui\". İsimlerde \"plus de … que\" kullanılır. Örnekler: \"plus grand que\", \"moins cher que\", \"aussi rapide que\"."],"superlatifs":["Üstünlük derecesi","\"plus\" veya \"moins\" önüne belirli tanımlık koyun: \"le plus grand\", \"la plus belle\", \"les moins chers\". 'içinde' için \"de\" denir: \"le plus grand de la classe\". Örnekler: \"le plus grand\", \"la plus belle\", \"les moins chers\"."],"meilleur-mieux":["meilleur mü, mieux mü?","\"bon\" -> \"meilleur\" (sıfat, uyar): \"une meilleure idée\". \"bien\" -> \"mieux\" (zarf, değişmez): \"elle chante mieux\". Asla \"plus bon\" ya da \"plus bien\" demeyin. Örnekler: \"meilleur\", \"mieux\", \"la meilleure idée\"."],"adverbes-ment":["-ment zarfları","Dişil sıfata \"-ment\" ekleyin: \"lent\" -> \"lentement\", \"heureux\" -> \"heureusement\". Ünlüyle bitenlerde eril biçime eklenir: \"vrai\" -> \"vraiment\". \"-ent\" \"-emment\" olur: \"prudent\" -> \"prudemment\". Örnekler: \"lentement\", \"vraiment\", \"prudemment\"."],"prep-pays-villes":["Ülkeler ve şehirler","Şehirler: \"à Paris\", \"de Paris\". Dişil ülkeler: \"en France\", \"de France\". Eril ülkeler: \"au Japon\", \"du Japon\". Çoğul ülkeler: \"aux États-Unis\", \"des États-Unis\". Örnekler: \"en France\", \"au Japon\", \"aux États-Unis\", \"à Paris\"."],"depuis-pendant-il-y-a":["depuis, pendant, il y a","\"depuis\" + présent: hâlâ süren bir şey (\"j'habite ici depuis deux ans\"). \"pendant\" + süre: ne kadar sürdüğü (\"j'ai dormi pendant huit heures\"). \"il y a\" + süre: ne kadar önce (\"il est parti il y a une heure\"). Örnekler: \"depuis deux ans\", \"pendant trois heures\", \"il y a une heure\"."],"passe-recent":["Yakın geçmiş: venir de","\"venir\" şimdiki zamanda çekilir ve \"de\" + mastar eklenir: \"je viens de finir\", \"nous venons de partir\". Ünlüden önce \"de\" \"d'\" olur: \"il vient d'arriver\". Örnekler: \"je viens de manger\", \"ils viennent de partir\"."],"imperatif-negatif":["Olumsuz emir","\"ne … pas\" emir fiilini sarar: \"ne pars pas !\", \"ne partons pas !\", \"ne partez pas !\". Zamirler fiilden önce kalır: \"ne le fais pas !\". Örnekler: \"ne parle pas\", \"ne partez pas\"."],"imperatif-pronoms":["Zamirlerle emir","Olumlu emirde zamir fiilden sonra gelir ve tireyle bağlanır: \"regarde-moi\", \"parlez-nous\", \"dis-lui\". \"me\" \"moi\" olur. Olumsuzda normal sıra korunur: \"ne me regarde pas\". Örnekler: \"regarde-moi\", \"dis-lui\", \"donne-le-moi\"."],"rel-qui-que":["qui ve que","\"qui\" özneyi karşılar: \"la femme qui habite ici\". \"que\" düz nesneyi karşılar: \"le film que nous regardons\". Ünlüden önce \"que\" \"qu'\" olur: \"le livre qu'il lit\". Örnekler: \"l'homme qui parle\", \"le livre que je lis\"."],"rel-ou":["où: nerede, ne zaman","\"où\" bir yeri ya da zamanı bir yan cümleye bağlar: \"la maison où elle habite\", \"le jour où nous sommes partis\". Hem yer hem zaman için işler. Örnekler: \"la ville où j'habite\", \"le jour où\"."],"il-faut":["il faut","\"il faut\" + mastar 'gerekir' demektir: \"il faut partir\". \"il faut\" + isim 'gerekir, lazım' demektir: \"il faut du temps\". Olumsuz \"il ne faut pas\" 'yapmamalısın' demektir. Kişisiz bir fiildir: yalnızca \"il\". Örnekler: \"il faut travailler\", \"il faut du temps\"."],"neg-jamais-plus-rien":["jamais, plus, rien, personne","\"pas\" yerine geçerler: \"ne … jamais\" (asla), \"ne … plus\" (artık değil), \"ne … rien\" (hiçbir şey), \"ne … personne\" (hiç kimse). \"rien\" ve \"personne\" özne de olabilir: \"personne ne vient\". Örnekler: \"je ne mange jamais\", \"il ne travaille plus\", \"nous ne voyons personne\"."],"quantite-de":["Miktar + de","Miktar sözcüklerinden sonra tanımlıksız \"de\" gelir: \"beaucoup de travail\", \"un peu de sucre\", \"assez de temps\", \"trop de monde\", \"peu de gens\", \"une bouteille d'eau\". Örnekler: \"beaucoup de travail\", \"un peu de sucre\", \"trop de monde\"."],"c-est-il-est":["c'est mi, il est mi?","Tek başına sıfat veya meslekle \"il est\" / \"elle est\" kullanın: \"il est médecin\", \"elle est gentille\". Tanımlık veya iyelik varsa \"c'est\" kullanın: \"c'est un médecin\", \"c'est mon frère\". Örnekler: \"c'est un médecin\", \"il est médecin\", \"elle est gentille\"."],"q-inversion":["Devrik soru","Özenli Fransızcada fiil özne zamirinin önüne geçer ve tireyle bağlanır: \"parlez-vous ?\", \"où vas-tu ?\", \"que font-ils ?\". Fiil ünlüyle bitiyorsa \"-t-\" eklenir: \"aime-t-il ?\". Örnekler: \"parlez-vous\", \"où vas-tu\", \"que font-ils\"."],"q-qui-que-quoi":["Kim ve ne","\"qui\" kişileri, \"que\" ve \"qu'est-ce que\" şeyleri sorar: \"qu'est-ce que tu fais ?\". Edattan sonra \"qui\" (kişi) ya da \"quoi\" (şey): \"avec qui ?\", \"de quoi parles-tu ?\". Örnekler: \"qui est-ce ?\", \"qu'est-ce que tu fais ?\", \"de quoi parles-tu ?\"."],"adj-irreguliers":["beau, nouveau, vieux","Bu üçünün eril ünlüden önce özel biçimi vardır: \"beau\" -> \"bel\", \"nouveau\" -> \"nouvel\", \"vieux\" -> \"vieil\". Dişil: \"belle\", \"nouvelle\", \"vieille\". Çoğul: \"beaux\", \"nouveaux\", \"vieux\". Örnekler: \"un bel homme\", \"une nouvelle voiture\", \"un vieil ami\"."],"connecteurs-temps":["Önce, sonra, en sonunda","\"d'abord\" (önce), \"ensuite\" veya \"puis\" (sonra), \"après\" (ardından), \"enfin\" (en sonunda) eylemleri sıraya koyar: \"d'abord je mange, puis je pars, enfin j'arrive\". Örnekler: \"d'abord\", \"ensuite\", \"puis\", \"enfin\"."],"si-present-futur":["si + présent, futur","Gerçekleşebilir bir ihtimal için: koşulda \"si\" + présent, sonuçta futur (veya emir). \"si tu viens, je serai content\", \"si vous avez le temps, appelez-moi\". \"si\" sonrasına asla futur koymayın. \"il\" önünde \"s'il\" olur. Örnekler: \"si tu viens, nous mangerons\", \"s'il pleut, je resterai\"."],"savoir-connaitre":["savoir mı, connaître mi?","\"savoir\" bilgi ve beceriler içindir: \"je sais nager\", \"je sais où il habite\". \"connaître\" kişileri, yerleri ve şeyleri tanımak içindir: \"je connais Marie\", \"je connais cette ville\". Örnekler: \"je sais nager\", \"je connais Paris\"."],"pres-irreguliers-2":["Daha düzensiz fiiller","Bunları gruplar hâlinde öğrenin: \"lire\" (\"nous lisons\"), \"dire\" (\"vous dites\"), \"écrire\" (\"ils écrivent\"), \"voir\" (\"nous voyons\"), \"boire\" (\"ils boivent\"). \"nous\" biçimi imparfait kurmaya yardım eder. Örnekler: \"nous lisons\", \"vous dites\", \"ils écrivent\"."],"meteo-il":["Hava durumu","\"il fait\" + sıfat (\"il fait beau, froid, chaud\") ve yağmur ile kar için bir fiil (\"il pleut\", \"il neige\") kullanın. Özne \"il\" boştur ve hiç değişmez. Soru: \"quel temps fait-il ?\" Örnekler: \"il fait beau\", \"il pleut\", \"il neige\"."],"profession-sans-article":["Mesleklerde tanımlık yok","\"être\" sonrasında meslek, uyruk veya din tanımlıksız gelir: \"il est médecin\", \"elle est française\". Sıfat varsa bunun yerine \"c'est un\" ekleyin: \"c'est un bon médecin\". Örnekler: \"elle est infirmière\", \"il est professeur\"."],"subj-il-faut-que":["Subjonctif: il faut que","\"il faut que\" sonrasında subjonctif kullanılır. Düzenli fiillerde \"ils\" présent kökünü alıp \"-e, -es, -e, -ions, -iez, -ent\" ekleyin: \"ils partent\" -> \"que je parte\". \"nous\" ve \"vous\" biçimleri imparfait'ye benzer. Örnekler: \"il faut que tu viennes\", \"il faut que je parte\"."],"subj-vouloir-que":["vouloir que + subjonctif","Özne değişince \"vouloir que\", \"préférer que\", \"aimer mieux que\" ve \"demander que\" subjonctif alır: \"je veux que tu viennes\". Özne aynıysa mastar kullanılır: \"je veux venir\". Örnekler: \"je veux que tu viennes\", \"elle veut que nous partions\"."],"subj-irreguliers":["Düzensiz subjonctif","Ezberleyin: \"être\" (\"que je sois\"), \"avoir\" (\"que j'aie, qu'il ait\"), \"aller\" (\"que j'aille\"), \"faire\" (\"que je fasse\"), \"pouvoir\" (\"que je puisse\"), \"savoir\" (\"que je sache\"), \"vouloir\" (\"que je veuille\"). Örnekler: \"que je sois\", \"qu'il ait\", \"que nous allions\", \"qu'ils fassent\"."],"subj-emotions":["Duygular + subjonctif","Duygu bildiren ifadelerden (\"être content que\", \"être triste que\", \"regretter que\", \"avoir peur que\", \"être surpris que\") sonra özne değişiyorsa subjonctif kullanılır. Örnekler: \"je suis content que tu sois là\", \"elle regrette que nous partions\"."],"subj-vs-indic":["Indicatif mi, subjonctif mi?","Kesinlik indicatif alır: \"je pense que\", \"je sais que\", \"il est sûr que\". Şüphe, inkâr ve istek subjonctif alır: \"je ne pense pas que\", \"je doute que\", \"il faut que\". Soruda \"Penser que\" ikisini de alabilir. Örnekler: \"je pense qu'il a raison\", \"je ne pense pas qu'il ait raison\"."],"subj-conjonctions":["Bağlaçlar + subjonctif","Bazı bağlaçlar hep subjonctif alır: \"pour que\" (-sin diye), \"avant que\" (-meden önce), \"bien que\" (-e rağmen), \"à condition que\" (şartıyla), \"jusqu'à ce que\" (-ene kadar). \"après que\" indicatif alır. Örnekler: \"pour que tu comprennes\", \"avant que tu partes\", \"bien qu'il soit fatigué\"."],"si-imparfait-cond":["si + imparfait, conditionnel","Hayalî veya zor ihtimalli durumlar için: \"si\" + imparfait, sonuçta conditionnel. \"si j'étais riche, je voyagerais\". \"si\" sonrasında asla conditionnel kullanmayın. Örnekler: \"si j'avais de l'argent\", \"j'achèterais une maison\"."],"cond-usage":["Conditionnel: öğüt ve dilek","\"conditionnel\" öğüt verir (\"tu devrais\"), dilek bildirir (\"j'aimerais\") ve nazik öneriler sunar (\"on pourrait\"). \"devoir\", \"pouvoir\" ve \"vouloir\" ile çok yaygındır. Örnekler: \"tu devrais dormir\", \"nous aimerions voyager\"."],"cond-passe-regret":["Geçmişe pişmanlık","Olmayan şeyler için: \"si\" + plus-que-parfait, sonuçta conditionnel passé. \"si tu avais étudié, tu aurais réussi\". Conditionnel passé, conditionnel'de \"avoir\" veya \"être\" + geçmiş zaman ortacıdır. Örnekler: \"si j'avais su\", \"je serais venu\"."],"plus-que-parfait-forme":["Plus-que-parfait: biçimler","\"imparfait\" kipinde yardımcı fiil + geçmiş zaman ortacı: \"j'avais mangé\", \"elle était partie\", \"nous nous étions levés\". \"avoir\" mı \"être\" mi ve uyum konusunda passé composé ile aynı kurallar geçerlidir. Örnekler: \"j'avais fini\", \"nous étions partis\", \"elle avait mangé\"."],"plus-que-parfait-usage":["Plus-que-parfait: kullanım","\"plus-que-parfait\", başka bir geçmiş eylemden veya geçmişteki bir andan önce olan eylem için kullanılır: \"quand je suis arrivé, il était déjà parti\". Sık sık bir nedeni açıklar: \"il était fatigué, il n'avait pas dormi\". Örnekler: \"le film avait déjà commencé\", \"il n'avait pas dormi\"."],"di-present":["Dolaylı anlatım (şimdiki)","Şimdiki zamanda \"dire que\", \"répondre que\", \"expliquer que\" ile aktarılan cümlenin zamanı değişmez; yalnızca zamirler ve \"mon\" gibi sözcükler değişir: \"« j'ai faim »\" -> \"il dit qu'il a faim\". Örnekler: \"il dit qu'il est fatigué\", \"elle répond qu'elle ne sait pas\"."],"di-questions":["Dolaylı sorular","Evet/hayır soruları \"si\" alır: \"il demande si tu viens\". Soru sözcükleri kalır: \"où, quand, comment, pourquoi\". \"Qu'est-ce que\" \"ce que\", \"qu'est-ce qui\" \"ce qui\" olur. Sözcük sırası düz cümlenin sırasıdır. Örnekler: \"il demande si je viens\", \"elle demande où j'habite\"."],"di-passe":["Dolaylı anlatım (geçmiş)","\"a dit que\" sonrasında zamanlar bir adım geri kayar: présent -> \"imparfait\", futur -> \"conditionnel\", passé composé -> \"plus-que-parfait\". Zaman sözcükleri de değişir: \"demain\" -> \"le lendemain\". Örnekler: \"il a dit qu'il était fatigué\", \"elle a répondu qu'elle viendrait\"."],"gerondif-formation":["Gérondif: biçimler","Présent'ın \"nous\" biçimini alın, \"-ons\" atın, \"-ant\" ekleyin ve önüne \"en\" koyun: \"nous travaillons\" -> \"en travaillant\". İstisnalar: \"être\" -> \"en étant\", \"avoir\" -> \"en ayant\", \"savoir\" -> \"en sachant\". Örnekler: \"en travaillant\", \"en lisant\", \"en finissant\"."],"gerondif-usage":["Gérondif: kullanım","\"gérondif\" iki eylemin birlikte olduğunu (\"il chante en travaillant\"), bir şeyin nasıl yapıldığını (\"on apprend en lisant\") veya bir koşulu (\"en tournant à gauche, vous verrez la poste\") bildirir. İki fiilin öznesi aynıdır. Örnekler: \"on apprend en lisant\", \"il s'est blessé en jouant\"."],"rel-dont":["dont: -in, ki onun","\"dont\", \"de\" + isim yerine geçer: \"je parle de ce livre\" -> \"le livre dont je parle\". Ayrıca 'kimin' anlamına gelir: \"la fille dont le père est médecin\". \"avoir besoin de\" sonrasında da: \"ce dont j'ai besoin\". Örnekler: \"le livre dont je parle\", \"la fille dont le père est médecin\"."],"rel-ce-qui-ce-que":["ce qui, ce que, ce dont","Önde isim yoksa \"ce qui\" (özne), \"ce que\" (nesne) ve \"ce dont\" (\"de\" ile) kullanılır: \"ce qui se passe\", \"ce que tu veux\", \"ce dont j'ai besoin\". Örnekler: \"ce que tu veux\", \"ce qui se passe\", \"ce dont j'ai besoin\"."],"pronoms-ordre":["İki zamir bir arada","Fiilden önce sıra: \"me, te, nous, vous\" + \"le, la, les\" + \"lui, leur\" + \"y\" + \"en\". \"me le\", \"te la\", \"nous les\", ama \"le lui\", \"les leur\": \"je le lui donne\". Örnekler: \"je le lui donne\", \"elle me les envoie\"."],"y-en-ensemble":["il y en a","\"y\" ve \"en\" birlikte geldiğinde önce \"y\" gelir: \"il y en a\", \"il n'y en a plus\". \"en\" miktarı korur: \"il y en a trois\". Örnekler: \"il y en a\", \"nous y en avons\"."],"imperatif-ordre-pronoms":["Emir: zamir sırası","Olumlu: fiil + düz nesne (\"le, la, les\") + dolaylı (\"moi, lui, nous, leur\") + \"y\" / \"en\": \"donne-le-moi\", \"dis-le-lui\". \"moi\" \"en\" önünde \"m'\" olur: \"donne-m'en\". Olumsuz: normal sıra, \"ne me le donne pas\". Örnekler: \"donne-le-moi\", \"dis-le-lui\", \"donne-m'en\"."],"pronoms-possessifs":["İyelik zamirleri","İyelik sözcüğü + ismin yerini tutar ve isme uyar: \"le mien, la mienne, les miens, les miennes\", \"le tien\", \"le sien\", \"le nôtre\", \"le vôtre\", \"le leur\". \"Où est ma clé ? — Voici la mienne.\" Örnekler: \"le mien\", \"la tienne\", \"les nôtres\"."],"pronoms-demonstratifs":["celui, celle, ceux, celles","'Olan(lar)' anlamında yer tutarlar ve ardından \"de\", \"qui\", \"que\" veya \"-ci / -là\" gelir: \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\", \"celles-là\". Örnekler: \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\"."],"pronoms-indefinis":["Belgisiz zamirler","\"quelqu'un\" (biri), \"quelque chose\" (bir şey), \"personne\" (hiç kimse), \"rien\" (hiçbir şey), \"chacun\" (herkes, her biri), \"plusieurs\" (birkaçı). Sıfattan önce \"de\" kullanılır: \"quelque chose de bon\". Örnekler: \"quelqu'un\", \"quelque chose de sucré\", \"chacun\"."],"adj-indefinis":["chaque, plusieurs, quelques","\"chaque\" + tekil isim (her), \"plusieurs\" ve \"quelques\" + çoğul isim (birkaç). \"tout\" uyar: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Örnekler: \"chaque élève\", \"plusieurs voitures\", \"toute la journée\"."],"pc-accord-cod":["avoir ile ortaç uyumu","\"avoir\" ile ortaç, yalnızca düz nesne fiilden önce geldiğinde ona uyar: \"j'ai acheté des fleurs\" ama \"les fleurs que j'ai achetées\", \"je les ai vues\". Örnekler: \"les fleurs que j'ai achetées\", \"je les ai vues\"."],"passif-forme":["Edilgen çatı","\"être\" (gereken zamanda) + özneye uyan geçmiş zaman ortacı + \"par\": \"la lettre est écrite par Paul\", \"les maisons ont été détruites par le feu\". Etken cümlenin nesnesi özne olur. Örnekler: \"le roman est écrit par\", \"la porte est ouverte par\"."],"se-passif":["se ile edilgen","Üçüncü kişide \"se\" ile kullanılan fiil, fail belirtilmeden edilgen anlam verir: \"le vin se vend ici\", \"ça ne se dit pas\", \"cela se voit\". Konuşmada ve kurallarda çok yaygındır. Örnekler: \"ça se dit\", \"ce produit se vend partout\"."],"etre-en-train-de":["être en train de","\"être en train de\" + mastar, bir eylemin tam şu an sürdüğünü vurgular: \"je suis en train de lire\". Israr etmek istediğinizde '-iyor' karşılığıdır: \"ne l'appelle pas, il est en train de dormir\". Örnekler: \"je suis en train de manger\", \"ils sont en train de partir\"."],"pc-avoir-transitif":["Aynı fiil, iki yardımcı","\"sortir, monter, descendre, passer, rentrer, retourner\" düz nesne alınca yardımcı fiil \"avoir\" olur: \"j'ai sorti la voiture\", \"elle a monté les escaliers\". Nesnesizse \"être\": \"elle est sortie\". Örnekler: \"il a sorti la valise\", \"elle a monté les escaliers\"."],"futur-anterieur":["Futur antérieur","Futur simple'de \"avoir\" veya \"être\" + geçmiş zaman ortacı: \"j'aurai fini\", \"elle sera partie\". Başka bir gelecek eylemden önce tamamlanmış eylemi anlatır: \"quand j'aurai fini, je t'appellerai\". Örnekler: \"quand j'aurai fini\", \"dès qu'elle sera arrivée\"."],"quand-futur":["quand + futur","Türkçeden farklı olarak, eylem gelecekteyse Fransızca \"quand\", \"dès que\", \"lorsque\" ve \"aussitôt que\" sonrasında futur kullanır: \"dès qu'il arrivera, nous partirons\". \"Si\" istisnadır: asla futur almaz. Örnekler: \"quand je serai grand\", \"dès qu'il arrivera\"."],"connecteurs-cause-consequence":["Neden ve sonuç","\"car\" ve \"parce que\" neden bildirir; \"comme\" ve \"puisque\" bilinen bir nedenle cümleyi başlatır: \"comme il pleut, je reste\". \"donc\" ve \"alors\" sonucu verir: \"il pleut, donc je reste\". Örnekler: \"donc\", \"car\", \"comme\", \"puisque\"."],"connecteurs-opposition":["Karşıtlık","\"mais\", \"pourtant\" ve \"cependant\" iki fikri karşı karşıya koyar. \"alors que\" iki olguyu kıyaslar: \"elle aime le thé, alors que son mari préfère le café\". \"malgré\" + isim '-e rağmen' demektir: \"malgré la pluie\". Örnekler: \"pourtant\", \"alors que\", \"malgré la pluie\"."],"but-pour-afin-de":["Amaç","Özne aynıysa: \"pour\" veya \"afin de\" + mastar: \"je travaille pour gagner de l'argent\". Özne farklıysa: \"pour que\" veya \"afin que\" + subjonctif: \"il parle lentement pour que nous comprenions\". Örnekler: \"pour gagner de l'argent\", \"afin de rentrer\", \"pour que nous comprenions\"."],"neg-ne-que-ni":["ne … que, ni … ni, aucun","\"ne … que\" 'yalnızca' demektir: \"je n'ai que dix euros\". \"ne … ni … ni\" 'ne ... ne de' demektir: \"elle ne mange ni viande ni poisson\". \"ne … aucun\" 'hiç ... yok' demektir: \"il n'a aucun ami\". Örnekler: \"je n'ai que dix euros\", \"ni viande ni poisson\", \"aucun ami\"."],"neg-infinitif":["Olumsuz mastar","Olumsuzluğun iki parçası mastardan önce birlikte gelir: \"ne pas partir\", \"ne plus fumer\", \"ne jamais mentir\". \"Il m'a demandé de ne pas fumer\". Örnekler: \"ne pas fumer\", \"ne plus travailler\", \"ne jamais mentir\"."],"q-lequel":["Lequel: hangisi","\"lequel\", \"quel\" + ismin yerine geçer ve uyar: \"lequel\" (eril tekil), \"laquelle\" (dişil tekil), \"lesquels\" (eril çoğul), \"lesquelles\" (dişil çoğul). \"Quel sac ? Lequel ?\" \"à\" ve \"de\" sonrasında: \"auquel\", \"duquel\". Örnekler: \"lequel\", \"laquelle\", \"lesquels\"."],"exclamations":["Ünlemler","\"quel\" + isim: \"quelle belle journée !\". \"comme\" veya \"que\" + cümle: \"comme il fait chaud !\", \"que c'est joli !\". Fransızcada \"!\" işaretinden önce boşluk bırakıldığına dikkat edin. Örnekler: \"quelle belle journée !\", \"comme il fait chaud !\", \"que c'est joli !\"."],"adv-place-pc":["passé composé'da kısa zarflar","Kısa ve sık zarflar (\"déjà, bien, mal, souvent, toujours, encore, trop, beaucoup\") yardımcı fiil ile ortaç arasına girer: \"j'ai déjà mangé\", \"il a bien compris\". Yer zarfları ve uzun zarflar sonra gelir. Örnekler: \"elle a déjà fini\", \"il a bien compris\"."],"comparatifs-avances":["Gittikçe, ne kadar ... o kadar","\"de plus en plus\" (gittikçe daha), \"de moins en moins\" (gittikçe daha az), \"plus … plus\" (ne kadar ... o kadar), \"autant de … que\" (kadar çok): \"elle a autant de livres que moi\". Örnekler: \"de plus en plus froid\", \"plus on travaille, plus on apprend\", \"autant de livres\"."],"prep-verbes":["Edatlı fiiller","Birçok fiil sabit bir edat ister: \"penser à\", \"s'intéresser à\", \"répondre à\", \"parler de\", \"avoir besoin de\", \"avoir envie de\", \"rêver de\". Bunları fiille birlikte öğrenin. Örnekler: \"penser à\", \"parler de\", \"avoir besoin de\", \"s'intéresser à\"."],"prep-temps-en-dans":["en mi, dans mı?","\"dans\" + süre: şimdiden sayılarak bir şeyin ne zaman olacağı (\"le film commence dans une heure\"). \"en\" + süre: bir şeyin ne kadar sürdüğü (\"il a lu ce livre en deux jours\"). \"en\" ayrıca aylar ve yıllarla gelir: \"en mai\", \"en 1998\". Örnekler: \"dans une heure\", \"en deux jours\"."],"inf-apres-prepositions":["Edatlar + mastar","\"avant de\" + mastar, \"après\" + geçmiş mastar (\"avoir\" veya \"être\" + ortaç), \"sans\" + mastar: \"avant de partir\", \"après avoir mangé\", \"sans dire au revoir\". Özne aynı olmalıdır. Örnekler: \"avant de manger\", \"après avoir mangé\", \"sans dire\"."],"faire-causatif":["faire + mastar","\"faire\" + mastar, bir şeyi yaptırmak (\"je fais réparer ma voiture\") veya birine bir şey yaptırmak (\"il fait rire les enfants\") demektir. Mastar doğrudan \"faire\"den sonra gelir. Örnekler: \"je fais réparer ma voiture\", \"il fait rire les enfants\"."],"verbes-perception":["Görmek, duymak + mastar","\"voir\", \"entendre\", \"regarder\", \"écouter\", \"sentir\" sonrasında mastar gelir: \"je les entends jouer\", \"nous voyons passer le train\". Zamir, algı fiilinin nesnesidir. Örnekler: \"je les entends chanter\", \"nous voyons passer le train\"."],"voyelle-liaison-ecrite":["Ünlüden önce özel biçimler","Ünlü veya sessiz h'den önce bazı sözcükler söylemeyi kolaylaştırmak için değişir: \"ma\" -> \"mon\" (\"mon amie\"), \"ce\" -> \"cet\" (\"cet homme\"), \"beau\" -> \"bel\" (\"un bel arbre\"), \"nouveau\" -> \"nouvel\", \"vieux\" -> \"vieil\". Örnekler: \"mon amie\", \"cet homme\", \"un bel arbre\"."],"tout-tous-toutes":["tout, tous, toute, toutes","Sıfat olarak \"tout\" uyar: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Zamir olarak 'her şey' (\"j'ai tout compris\") veya 'hepsi' (\"ils sont tous là\", son -s okunur) demektir. Örnekler: \"tous les jours\", \"toute la journée\", \"ils sont tous là\"."],"subj-after-bien-que":["Bien que + subjonctif","\"bien que\", \"quoique\" ve \"encore que\" karşıtlık (-e rağmen) bildirir ve olgu kesin olsa bile her zaman subjonctif alır. \"Bien que le projet soit coûteux, nous continuons\" denir, \"bien que le projet est\" denmez. Örnekler: \"Bien qu'il pleuve, nous sortons\", \"Quoiqu'elle soit jeune, elle dirige l'équipe\"."],"subj-after-pour-que":["Amaç: pour que, afin que","\"pour que\" ve \"afin que\" amaç bildirir, ardından subjonctif gelir. Amaç cümlesinin öznesi genellikle ana cümlenin öznesinden farklıdır: \"Je répète pour que vous compreniez\". Özne aynıysa \"pour\" veya \"afin de\" ile mastar kullanılır. Örnekler: \"Il parle lentement pour que nous comprenions\", \"Elle écrit afin que tout soit clair\"."],"subj-after-avant-que":["Zaman sınırı: avant que","\"avant que\" ve \"jusqu'à ce que\", eylem henüz gerçekleşmediği için subjonctif alır. \"avant que\" sonrasına çoğu zaman olumsuz anlamı olmayan bir \"ne\" eklenir: \"avant qu'il ne parte\". Özne aynıysa \"avant de\" ile mastar kullanılır. Örnekler: \"Attends jusqu'à ce que je revienne\", \"Appelle avant que nous ne partions\"."],"subj-a-moins-que-ne":["İstisna: à moins que","\"à moins que\" \"-medikçe\" anlamına gelir ve subjonctif gerektirir. Resmî Fransızcada fiilin önüne çoğu zaman gerçek olumsuzluk taşımayan bir \"ne\" eklenir (\"à moins qu'il ne vienne\"). Ardından koşul kipi ya da gelecek zaman kullanılmaz. Örnekler: \"Je sors, à moins qu'il ne pleuve\", \"à moins que vous ne soyez occupé\"."],"subj-a-condition-que":["Koşul: à condition que","\"à condition que\" ve \"pourvu que\" \"-mek şartıyla\" anlamına gelir ve subjonctif alır; gelecek zaman ya da koşul kipi asla kullanılmaz. \"Pourvu que\" cümle başında umut da bildirebilir: \"Pourvu qu'il vienne !\". Örnekler: \"Je viendrai à condition que vous m'invitiez\", \"Pourvu que tout se passe bien\"."],"subj-vs-ind-opinion":["Görüş fiilleri: kip seçimi","Olumlu cümlede \"penser que\" ve \"croire que\" sonrasında indicatif kullanılır: \"Je pense qu'il a raison\". Olumsuzda ya da devrik soruda şüphe belirir ve subjonctif gelir: \"Je ne pense pas qu'il ait raison\". Kip, konuşanın ne kadar emin olduğuna bağlıdır. Örnekler: \"Je crois qu'elle viendra\", \"Je ne crois pas qu'elle vienne\"."],"subj-emotion-doubt":["His, şüphe, gereklilik","Duygu (\"être content que\", \"regretter que\"), şüphe (\"douter que\") ve gereklilik (\"il faut que\", \"il est essentiel que\") fiillerinden sonra, özneler farklıysa subjonctif gelir. Cümle düz bir olguyu değil, bir tepkiyi ya da ihtiyacı anlatır. Örnekler: \"Je suis ravi que vous veniez\", \"Il faut que nous partions\"."],"subj-irregular-forms":["Düzensiz subjonctif kökleri","Yedi yaygın fiilin subjonctif kökü düzensizdir: \"être\" (sois, soyons), \"avoir\" (aie, ayons), \"aller\" (aille, allions), \"faire\" (fasse), \"pouvoir\" (puisse), \"savoir\" (sache), \"vouloir\" (veuille). Bunları bütün biçimleriyle öğren; \"être\", \"avoir\", \"aller\" ve \"vouloir\" fiillerinin nous ve vous biçimlerinin de kendi kökü vardır. Örnekler: \"qu'elle aille\", \"que vous sachiez\", \"que tu aies\"."],"subj-passe":["Geçmiş subjonctif","Geçmiş subjonctif, \"avoir\" ya da \"être\" fiilinin subjonctif'i ile geçmiş ortaç birleşiminden oluşur. Eylemin ana fiilden önce bittiğini gösterir: \"Je suis content que tu sois venu\". Yardımcı fiil passé composé'deki gibi seçilir, uyum korunur. Örnekler: \"Il faut qu'ils aient fini\", \"Bien qu'elle soit partie\"."],"subj-vs-infinitive":["Subjonctif mi, mastar mı","İki fiilin öznesi aynıysa Fransızca mastarı tercih eder: \"Je veux partir\". Özne değişirse \"que\" ile subjonctif kullanılır: \"Je veux que tu partes\". Aynısı istekler, duygular ve birçok bağlaç için de geçerlidir (\"avant de\" ya da \"avant que\"). Örnekler: \"Elle est contente d'être là\", \"Elle est contente que vous soyez là\"."],"subj-superlative-relative":["Üstünlük sonrası subjonctif","Üstünlük ifadesinden (\"le plus\", \"le meilleur\") ya da \"seul\", \"premier\", \"dernier\", \"unique\" sözcüklerinden sonra ilgi cümlesi subjonctif alır, çünkü ifade kişisel bir yargıdır. \"jamais\" ile geçmiş subjonctif yaygındır: \"le plus beau film que j'aie vu\". Örnekler: \"le seul homme qui sache\", \"la première fois que je le voie\"."],"subj-relative-search":["Aranan nesne için subjonctif","İlgi cümlesi aradığın, istediğin ya da var olduğundan şüphe ettiğin bir şeyi anlatıyorsa subjonctif kullan: \"Je cherche un livre qui soit simple\". Şeyin var olduğunu biliyorsan indicatif kullan: \"J'ai un livre qui est simple\". Tipik tetikleyiciler: \"chercher\", \"vouloir\", \"il n'y a personne qui\", varlık soruları. Örnek: \"Y a-t-il quelqu'un qui puisse m'aider ?\"."],"cond-passe-news":["Doğrulanmamış haber için koşul kipi","Gazeteciler doğrulanmamış bilgiyi aktarmak için koşul kipini, çoğu zaman geçmiş koşul kipini kullanır: \"Le ministre aurait démissionné\". \"İddiaya göre\" anlamı verir ve yazarı olgunun güvencesinden kurtarır. Güncel söylenti için koşul kipi şimdiki zaman kullanılır: \"Il serait malade\". Örnekler: \"Deux personnes seraient blessées\", \"selon certaines sources, le vol aurait été annulé\"."],"si-plus-que-parfait":["Gerçek dışı geçmiş: si + plus-que-parfait","Geçmişteki gerçek dışı koşul için \"si\" ile plus-que-parfait, sonuçta ise geçmiş koşul kipi kullanılır: \"Si j'avais su, je serais venu\". Bu anlamda \"si\" sonrasında koşul kipi asla kullanılmaz. Sonuç cümlesi gerçekleşmeyeni gösterir. Örnekler: \"Si elle avait étudié, elle aurait réussi\", \"Si nous étions partis, nous aurions vu le concert\"."],"si-mixed-conditions":["Karma koşul cümleleri","Karma koşul cümlesi geçmişteki bir koşulu şimdiki bir sonuca bağlar: \"si\" ile plus-que-parfait, ardından şimdiki zaman koşul kipi. Sonuçtaki \"maintenant\" ya da \"aujourd'hui\" gibi zaman sözcükleri, sonucun hâlâ geçerli olduğunu gösterir. Örnek: \"Si tu avais écouté, tu comprendrais\". Tamamen geçmiş kalıpla karşılaştır: \"tu aurais compris\"."],"hypothese-au-cas-ou":["Önlem: au cas où","\"au cas où\" olası bir olaya karşı önlemi bildirir ve ardından koşul kipi gelir; subjonctif ya da gelecek zaman gelmez. \"Ya ... olursa diye\" anlamındadır. Cümlenin başında ya da sonunda yer alabilir. Örnekler: \"Prenez un parapluie au cas où il pleuvrait\", \"Au cas où tu serais en retard, appelle-moi\"."],"apres-que-indicatif":["après que + indicatif","\"après que\" ve \"dès que\" gerçekten olmuş bir olguyu bildirir, bu yüzden (\"avant que\"nin aksine) subjonctif değil indicatif alır. \"après que\" sonrasındaki fiil, ana fiilden önce gelen bileşik bir zamandadır: \"Après qu'il a fini, il est rentré\". Ana fiil gelecekteyse \"dès que\" ile futur antérieur kullanılır: \"Dès que tu auras fini, appelle-moi\"."],"concordance-des-temps":["Zaman uyumu","Ana fiil geçmiş zamandaysa yan cümle fiili bir adım geriye gider: şimdiki zaman imparfait, passé composé plus-que-parfait, gelecek zaman koşul kipi olur. Geçmiş zamanlı ana fiille şimdiki zamanlı yan cümle fiilini karıştırma: \"Il pensait que nous étions partis\". Örnekler: \"Je savais que tu viendrais\", \"Elle disait qu'elle était fatiguée\"."],"discours-indirect-passe":["Geçmişte dolaylı anlatım","Geçmiş zamanlı bir fiilden (\"elle a dit que\") sonra dolaylı anlatımda zamanlar kayar: şimdiki zaman imparfait'ye, passé composé plus-que-parfait'ye, gelecek zaman koşul kipine dönüşür. Zaman sözcükleri de değişir: \"demain\" \"le lendemain\", \"hier\" \"la veille\", \"aujourd'hui\" \"ce jour-là\" olur. Örnek: \"Il a dit qu'il viendrait le lendemain\"."],"discours-indirect-questions":["Dolaylı sorular","Dolaylı soruda normal sözcük sırası kullanılır, soru işareti konmaz. \"Est-ce que\" ve evet/hayır soruları \"si\" olur: \"Il a demandé si je venais\". \"Qu'est-ce que\" \"ce que\", \"qu'est-ce qui\" ise \"ce qui\" olur. Geçmiş zamanlı fiilden sonra zamanlar da kayar. Örnekler: \"Elle m'a demandé ce que je voulais\", \"Il voulait savoir ce qui se passait\"."],"discours-indirect-ordres":["Emir ve ricaları aktarma","Bir emri ya da ricayı aktarmak için \"dire de\" veya \"demander de\" ile mastar kullanılır: \"Elle m'a dit de rentrer\". Muhatap \"à\" ya da bir zamirle belirtilir: \"Il a demandé à ses voisins de baisser la musique\". Olumsuz emirde \"ne pas\" mastarın önünde bir arada durur: \"Il nous a dit de ne pas toucher aux câbles\"."],"accord-participe-cod-avant":["Öne geçen nesneyle uyum","\"avoir\" ile geçmiş ortaç, doğrudan nesneyle yalnızca nesne fiilden önce geldiğinde uyum sağlar. \"que\", \"les\" gibi bir zamire ya da soru sözcüğüne bak: \"Les lettres que Marie a écrites\", \"Quelle robe as-tu choisie ?\". Nesne sonra gelirse uyum olmaz: \"Marie a écrit des lettres\"."],"accord-participe-pronominaux":["Dönüşlü fiillerde ortaç uyumu","Dönüşlü fiilin passé composé'sinde, dönüşlü zamir doğrudan nesneyse ortaç onunla uyum sağlar: \"Les amies se sont retrouvées\". Zamir dolaylıysa ya da başka bir nesne geliyorsa ortaç değişmez: \"Elle s'est lavé les mains\", \"Ils se sont envoyé des messages\". Kendine sor: \"se\" \"à qui ?\" mi yoksa \"qui ?\" mi anlamında?"],"participe-present-gerondif":["Ortaç, gérondif, sıfat","Gérondif \"en + -ant\" bir şeyin nasıl ya da ne zaman olduğunu söyler ve değişmez: \"Il s'est blessé en coupant du bois\". Şimdiki zaman ortacı bir yan cümlenin yerini tutar ve o da değişmez: \"Les enfants jouant dans le jardin\". Fiilimsi sıfat ismiyle uyum sağlar: \"une histoire fascinante\", \"des résultats surprenants\"."],"passif-et-alternatives":["Edilgen ve alternatifleri","Edilgen yapı \"être\" ile geçmiş ortaçtan kurulur: \"Les résultats ont été annoncés par le jury\". Fransızca çoğu zaman alternatifleri tercih eder: genel olgular için dönüşlü fiil (\"Le fromage se mange après le plat\"), \"on\" ya da öznenin başına gelen için \"se faire\" (\"Il s'est fait voler son sac\")."],"causatif-faire-laisser":["Ettirgen faire ve laisser","\"Faire\" ile mastar bir şeyi yaptırmak anlamına gelir: \"Nous avons fait refaire la cuisine\". \"Laisser\" ile mastar izin vermek anlamına gelir: \"Le professeur a laissé les élèves partir\". Mastardan önce \"fait\" ortacı değişmez: \"Ce film m'a fait pleurer\"."],"pronoms-relatifs-composes":["Birleşik ilgi zamirleri","Edatın ardından isme göre \"lequel\", \"laquelle\", \"lesquels\" ya da \"lesquelles\" kullanılır: \"la table sur laquelle\", \"les amis chez lesquels\". \"à\" ile kaynaşırlar: \"auquel\", \"auxquels\", \"auxquelles\", \"à laquelle\". \"de\" ile \"duquel\", \"desquels\", \"de laquelle\" olur."],"pronom-relatif-dont":["İlgi zamiri dont","\"Dont\", ilgi cümlesinde \"de\" ile ismin yerini tutar: \"L'ordinateur dont j'ai besoin\" (avoir besoin de). Aidiyeti de bildirir; isim hemen ardından gelir: \"l'écrivain dont le dernier roman\". Bir grubun bir kısmını da getirir: \"trois enfants, dont deux vivent à l'étranger\"."],"ce-qui-ce-que-ce-dont":["Ce qui, ce que, ce dont","\"Ce\" ile ilgi zamiri bir düşünceye ya da adı geçmeyen bir şeye işaret eder. \"Ce qui\" özne (\"Ce qui m'inquiète\"), \"ce que\" nesnedir (\"ce que tu veux\"). \"de\" alan fiillerde \"ce dont\" (\"ce dont tu as envie\"), \"à\" alan fiillerde \"ce à quoi\" (\"ce à quoi il s'intéresse\") kullanılır."],"pronoms-doubles-ordre":["İki zamirin sırası","Fiilden önce me, te, nous ve vous için önce dolaylı zamir gelir: \"Je te le rends\". Üçüncü kişilerde önce doğrudan zamir gelir: \"Je le lui donne\"; \"en\" her zaman sonda yer alır: \"Je lui en ai parlé\". Olumlu emirden sonra sıra doğrudan, sonra dolaylıdır: \"Donne-les-moi\"."],"pronoms-y-en-avances":["y ve en ileri düzey","\"En\", \"de\" ile isim ya da miktarın yerini tutar ve sayı kalır: \"J'en ai acheté trois\". \"Y\", \"à\" ya da yerin yerini tutar: \"J'y pense tout le temps\". Olumlu emirde fiilin ardından gelir ve birleşebilirler: \"Donnez-m'en un kilo\"."],"mise-en-relief":["Vurgu: c'est...qui/que","\"C'est ... qui\" özneyi, \"c'est ... que\" ise nesneyi ya da tümleci vurgular: \"C'est moi qui ai fait le gâteau\", \"C'est demain que nous partons\". Çoğul isimle \"ce sont\" kullanılır: \"Ce sont mes voisins que j'ai invités\". \"qui\" sonrasındaki fiil, vurgulanan öğeyle uyum sağlar."],"inversion-peut-etre":["Cümle zarflarından sonra devrik yapı","Resmî Fransızcada cümle başındaki \"peut-être\", \"sans doute\" ve \"aussi\" (\"bu yüzden\" anlamında) sonrasında özne-fiil devrikliği olur: \"Peut-être viendra-t-il demain\". Özne isimse bir zamirle yinelenir. Fiil sesli harfle bitip \"il\" ya da \"elle\" geliyorsa \"-t-\" eklenir: \"viendra-t-elle\"."],"ne-expletif":["Anlamsız ne","Korku fiillerinden (\"craindre que\"), \"avant que\"den ve eşitsizlik karşılaştırmalarından sonra resmî Fransızca, olumsuz anlamı olmayan bir \"ne\" ekler: \"Je crains qu'il ne pleuve\", \"avant qu'il ne fasse nuit\", \"plus grand que je ne pensais\". Konuşmada isteğe bağlıdır, asla \"pas\" almaz."],"connecteurs-concession-opposition":["Karşıtlık ve zıtlık","\"Bien que\" ile subjonctif ve \"malgré\" ile isim karşıtlık bildirir: \"Malgré la pluie, nous sommes sortis\". \"Alors que\" ile indicatif iki olguyu karşılaştırır: \"Paul adore la mer, alors que sa femme préfère la montagne\". \"Pourtant\", \"cependant\" ve \"en revanche\" iki cümleyi bağlar."],"nominalisation":["Fiilleri isme çevirme","İsimleştirme yazıyı daha kısa ve resmî yapar. Fiiller -tion, -ment, -ure ya da -ée gibi eklerle isim olur: \"ouvrir\" \"l'ouverture\", \"augmenter\" \"l'augmentation\", \"arriver\" \"l'arrivée\" verir. Sıfatlar da olur: \"difficile\" \"la difficulté\" verir. Yeni ismin cinsiyetini kontrol et."],"tout-accord":["Tout: sıfat, zamir, zarf","Sıfat olarak \"tout\" isimle uyum sağlar: \"tous les magasins\", \"toutes les fenêtres\". \"Oldukça\" anlamlı zarf olarak değişmez; ancak ünsüzle başlayan dişil sıfatın önünde değişir: \"elle est tout étonnée\" ama \"elles sont toutes timides\"."],"prepositions-apres-verbes":["Fiillerden sonra edatlar","Bazı fiiller sabit bir edat alır ve edat anlamı değiştirebilir. \"Penser à\" bir şeyi düşünmek demektir: \"Je pense à mes vacances\"; \"penser de\" görüş sorar: \"Que penses-tu de ce film ?\". \"s'habituer à\" ve \"se méfier de\" gibi çiftleri tek bir bütün olarak öğren."],"infinitif-passe":["Geçmiş mastar","\"Après\" ile \"avoir\" ya da \"être\" ve geçmiş ortaç, bir eylemin ana eylemden önce olduğunu söyler: \"Après avoir écrit la lettre, il l'a postée\". İki eylemin öznesi aynı olmalıdır. Hareket fiilleri ve dönüşlü fiiller \"être\" alır ve uyum sağlar: \"Après être rentrée\", \"Après nous être reposés\"."],"a-regard-pronoms-lequel":["Soru zamiri lequel","\"Lequel\", bilinen şeyler arasında seçim sorar ve onlarla uyum sağlar: \"Lequel de ces chemins ?\", \"Laquelle de tes amies ?\". \"à\" ya da \"de\" ile kaynaşır: \"Auquel de ces clients as-tu téléphoné ?\", \"Duquel parles-tu ?\". \"Quel\" yalnızca isimden hemen önce kullanılır."]};
